(function(){
  var Reg = Java.loadClass('net.minecraft.core.registries.BuiltInRegistries');
  var RL = Java.loadClass('net.minecraft.resources.ResourceLocation');
  var SH = Java.loadClass('net.neoforged.neoforge.server.ServerLifecycleHooks');
  var server = SH.getCurrentServer();
  if (server === null) { return { ok: false, reason: 'no-server' }; }
  var chips = 0;
  var it = server.getRecipeManager().getRecipes().iterator();
  while (it.hasNext()) { var h = it.next(); if (String(h.id().getPath()).endsWith('_chip')) { chips++; } }
  return {
    ok: true,
    item_lingling: Reg.ITEM.containsKey(RL.parse('astral_dice:lingling_sign')),
    effect_surge: Reg.MOB_EFFECT.containsKey(RL.parse('astral_dice:lingling_surge')),
    chips: chips,
    players: server.getPlayerList().getPlayerCount()
  };
})()

(function(){
  var MC = Java.loadClass('net.minecraft.client.Minecraft');
  var mc = MC.getInstance();
  return { ok: true, fps: mc.getFps(), in_world: mc.level !== null, has_screen: mc.screen !== null };
})()

(function(){
  var SH = Java.loadClass('net.neoforged.neoforge.server.ServerLifecycleHooks');
  var s = SH.getCurrentServer();
  return (s !== null) && (s.getPlayerList().getPlayerCount() > 0);
})()
